/* eslint no-console:0 import/extensions:0 */
import 'fantd/src/modal/style/index.less';
import 'fantd/src/modal/style/confirm.less';
import 'fantd/src/modal/style/notice.less';
import React from 'react';
import { Modal } from 'fantd';
import ReactDOM from 'react-dom';

class Component extends React.Component {

    constructor() {
        super();
        this.state = {
            visible: false
        }
    }

    showModal = () => {
        this.setState({
            visible: true
        });
    }

    handleOk = () => {
        this.setState({
            visible: false
        });
    }

    handleCancel = () => {
        this.setState({
            visible: false
        });
    }

    showConfirm = () => {
        Modal.confirm({
            title: "哈哈哈",
            content: "该小区不是你的责任盘，仅能暂存，若30分钟内没有责任盘的经纪人录入该房源，则可以提交申请！",
            onOk: ()=>{
                console.log("点击了确定");
            },
            onCancel: ()=>{
                console.log("点击了取消");
            }
        });
    }

    showInfo = () => {
        Modal.info({
            title: "哈哈哈",
            content: "该小区不是你的责任盘，仅能暂存，若30分钟内没有责任盘的经纪人录入该房源，则可以提交申请！",
            onOk: ()=>{
                console.log("点击了确定");
            },
            onCancel: ()=>{
                console.log("点击了取消");
            }
        });
    }

    showSuccess = () => {
        Modal.success({content:"该小区不是你的责任盘，仅能暂存", duration: 100,className: 'modal-wrap'});
    }

    showError = () => {
        Modal.error({content:"错误"});
    }

    showWarn = () => {
        Modal.warn({content:"警告"});
    }

    showLoading = () => {
        Modal.loading({content:"正在加载应用" ,duration:100});
    }
    

    render() {
        const { visible } = this.state;

        return (
            <div >
                {/* ref="modal" */}
                <div onClick={this.showModal} style={{ cursor: "pointer", fontSize: "14px", marginBottom: "20px" }}><bold>点击展现普通弹框</bold></div>
                <div onClick={this.showConfirm} style={{ cursor: "pointer", fontSize: "14px", marginBottom: "20px" }}><bold>点击展现确认取消框</bold></div>
                <div onClick={this.showInfo} style={{ cursor: "pointer", fontSize: "14px", marginBottom: "20px" }}><bold>点击展现确认框</bold></div>
                <div onClick={this.showSuccess} style={{ cursor: "pointer", fontSize: "14px", marginBottom: "20px" }}><bold>点击展现成功提示</bold></div>
                <div onClick={this.showError} style={{ cursor: "pointer", fontSize: "14px", marginBottom: "20px" }}><bold>点击展现失败提示</bold></div>
                <div onClick={this.showWarn} style={{ cursor: "pointer", fontSize: "14px", marginBottom: "20px" }}><bold>点击展现警告提示</bold></div>
                <div onClick={this.showLoading} style={{ cursor: "pointer", fontSize: "14px", marginBottom: "20px" }}><bold>点击展现加载提示</bold></div>
                <Modal
                    title="小框框"
                    visible={visible}
                    onOk={this.handleOk}
                    onCancel={this.handleCancel}
                    width={520}
                    // wrapClass="a"
                    // getContainer={() => this.refs.modal}
                >
                    <div style={{ textAlign: 'center', fontSize: "16px", padding: "20px" }}>
                        1.食用方式和antd的modal一样<br />
                        2.width是模态框的宽度, 默认为444<br />
                        3.onOk是右边点击的回调, 默认为null<br />
                        4.onCancel是左边点击的回调, 默认为null<br />
                        5.okText是右边的文字，也可传递组件进去进行控制, 默认为保存<br />
                        6.cancelText是左边按钮的文字, 也可传递组件进去进行控制, 默认为关闭<br />
                        7.title当然是中间的标题了, 也可传递组件进去进行控制, 默认为空""<br />
                        8.maskClosable指的是点击阴影是否关闭, 默认为true<br />
                    </div>
                </Modal>
            </div>
        )
    }
}

ReactDOM.render(<Component />, document.getElementById('__react-content'));



